#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# Run from the repo root. Values land in .dev.vars (git-ignored), the file
# Wrangler reads as Worker secrets in local dev; at deploy they go in with
# `wrangler secret put`. Non-secret notes for the ticket go to LOG_FILE.
ENV_FILE=".dev.vars"
LOG_FILE=".scratch/dance-calendar-mvp/wizards/meta-setup-log.md"
GRAPH="https://graph.facebook.com/v26.0"
TOTAL_STAGES=11

log() { printf -- '- %s\n' "$1" >> "$LOG_FILE"; }
started=$(date +%s)
[[ -f "$LOG_FILE" ]] || printf '# Meta / WhatsApp setup log (no secrets)\n\n' > "$LOG_FILE"
log "Run started $(date '+%Y-%m-%d %H:%M')"

banner "DanceCalendar: Meta business portfolio + WhatsApp number"

stage "Dedicated prepaid SIM"
say "The bot needs its own number that has never been registered on WhatsApp."
step "Buy a prepaid SIM (any German carrier; the ID check by video or Postident is required by law)."
step "Activate it and put it in a phone that can receive SMS or calls."
step "Do NOT install WhatsApp with this number: registered numbers can't be used until deleted."
ask WHATSAPP_DISPLAY_PHONE "Bot number in international format (e.g. +4915112345678):"
write_env WHATSAPP_DISPLAY_PHONE "$WHATSAPP_DISPLAY_PHONE"
ask SIM_CARRIER "Carrier / tariff (for the log, e.g. 'Aldi Talk Basis'):"
log "SIM: $SIM_CARRIER"

stage "Meta developer account"
say "Use the Admin's own Facebook account; turn on two-factor authentication if it isn't."
open_url "https://developers.facebook.com/async/registration/"
step "Finish developer registration (accept the Platform Terms, verify phone/email)."
pause "Press Enter once you're registered as a developer."

stage "App + business portfolio"
open_url "https://developers.facebook.com/apps"
step "Click 'Create App', name it 'DanceCalendar', enter your email."
step "Use case: 'Connect with customers through WhatsApp' → Next."
step "Business portfolio: 'Create a new one'. Note every field it asks for (legal name? address? website?)."
step "Finish with 'Create app'. The App ID is shown at the top of the App Dashboard."
ask WHATSAPP_APP_ID "Paste the App ID:"
write_env WHATSAPP_APP_ID "$WHATSAPP_APP_ID"
ask PORTFOLIO_FIELDS "Which fields did the portfolio form require, and did your own name work as the business name?"
log "Business portfolio: $PORTFOLIO_FIELDS"

stage "WhatsApp Business (Messaging) account"
step "In the app: 'Start using the API' → 'API Setup'."
step "Select 'Create a WhatsApp Business account' and follow the business-profile prompts."
step "The API Setup panel then shows the 'Messaging account ID' (WhatsApp Business Account ID)."
ask WHATSAPP_WABA_ID "Paste the WhatsApp Business Account ID:"
write_env WHATSAPP_WABA_ID "$WHATSAPP_WABA_ID"
note "Ignore the test number and the temporary token on that page."

stage "App secret"
say "The Worker checks every webhook's X-Hub-Signature-256 with this secret."
step "App Dashboard → App settings → Basic → App secret → Show (re-enter your password)."
ask_secret WHATSAPP_APP_SECRET "Paste the App secret (hidden):"
write_env WHATSAPP_APP_SECRET "$WHATSAPP_APP_SECRET"

stage "Add the bot number + display name"
open_url "https://business.facebook.com/latest/whatsapp_manager/"
step "WhatsApp Manager → Account tools → Phone numbers → Add phone number."
note "No access to WhatsApp Manager? Business Settings → Accounts → WhatsApp accounts →"
note "  your account → assign yourself full control; or use 'Add phone number' in the app's API Setup."
step "Display name: e.g. 'DanceCalendar' or 'Tanzkalender Kassel Göttingen' (it must describe the service)."
step "Verify the number with the SMS (or voice) code sent to the prepaid SIM."
step "Click the number: its 'Phone number ID' is shown in the details (also in API Setup)."
ask WHATSAPP_PHONE_NUMBER_ID "Paste the Phone number ID:"
write_env WHATSAPP_PHONE_NUMBER_ID "$WHATSAPP_PHONE_NUMBER_ID"
ask DISPLAY_NAME "Display name you entered:"
log "Display name requested: $DISPLAY_NAME"

stage "Permanent access token (system user)"
open_url "https://business.facebook.com/latest/settings"
step "Pick your portfolio top left, then in the sidebar: Users → System users."
step "Add+ → name 'dancecalendar-bot', role Admin → Create."
step "Select it → Assign assets: the app ('Manage app', full control) and the"
step "  WhatsApp account ('Manage WhatsApp Business accounts', full control) → Assign assets."
step "Generate token → app DanceCalendar → expiry 'Never' → permissions:"
step "  business_management, whatsapp_business_messaging, whatsapp_business_management."
ask_secret WHATSAPP_ACCESS_TOKEN "Paste the token (hidden):"
write_env WHATSAPP_ACCESS_TOKEN "$WHATSAPP_ACCESS_TOKEN"

stage "Register the number for the Cloud API"
say "Registration sets the number's two-step PIN; it only works via the API, so this wizard calls it."
if [[ -z "$(_existing WHATSAPP_2FA_PIN || true)" ]]; then
  write_env WHATSAPP_2FA_PIN "$(printf '%06d' $(( $(od -An -N4 -tu4 /dev/urandom) % 1000000 )))"
else
  WHATSAPP_2FA_PIN=$(_existing WHATSAPP_2FA_PIN)
fi
note "The PIN is in $ENV_FILE as WHATSAPP_2FA_PIN; copy it into your password manager too."
if confirm "Register $WHATSAPP_DISPLAY_PHONE now (max 10 tries per 72 h)?"; then
  reply=$(curl -sS -X POST "$GRAPH/$WHATSAPP_PHONE_NUMBER_ID/register" \
    -H "Authorization: Bearer $WHATSAPP_ACCESS_TOKEN" -H "Content-Type: application/json" \
    -d "{\"messaging_product\":\"whatsapp\",\"pin\":\"$WHATSAPP_2FA_PIN\"}" || true)
  say "Meta replied: $reply"
  if [[ "$reply" == *'"success":true'* ]]; then log "Number registered for Cloud API"
  else log "Registration failed: $reply"; warn "Not registered: fix the cause and re-run this wizard."; fi
else
  SKIPPED+=("Register the number (re-run the wizard)")
fi

stage "Payment method"
say "Without a card on file, service messages stop after the 1,000 free per month."
say "At our volume the bill should stay €0."
open_url "https://business.facebook.com/latest/settings/whatsapp_account"
step "Select the WhatsApp account → Payment methods / 'Add payment method' and add your card."
note "If that page has no such button, use the Billing hub instead:"
note "  https://business.facebook.com/latest/billing_hub/payment_methods/"
if confirm "Is a payment method now on the WhatsApp account?"; then log "Payment method on file"
else log "Payment method NOT added"; SKIPPED+=("Add a payment method to the WhatsApp account"); fi

stage "Webhook verify token (for later)"
say "The webhook can only be set once the Worker is deployed (it needs a public HTTPS URL)."
say "This generates the verify token now so the deploy ticket finds it in $ENV_FILE."
if [[ -z "$(_existing WHATSAPP_VERIFY_TOKEN || true)" ]]; then
  write_env WHATSAPP_VERIFY_TOKEN "$(openssl rand -hex 24)"
else
  note "WHATSAPP_VERIFY_TOKEN already set; keeping it."
fi

stage "Check it works"
reply=$(curl -sS "$GRAPH/$WHATSAPP_PHONE_NUMBER_ID?fields=display_phone_number,verified_name,name_status,code_verification_status,quality_rating,platform_type" \
  -H "Authorization: Bearer $WHATSAPP_ACCESS_TOKEN" || true)
say "Meta replied: $reply"
log "Number status: $reply"
note "name_status PENDING_REVIEW is fine for now; APPROVED or AVAILABLE_WITHOUT_REVIEW is the goal."
ask BLOCKERS "Anything that blocked you or surprised you? (Enter for none)" || BLOCKERS=""
log "Blockers / surprises: ${BLOCKERS:-none}"
log "Run took $(( ($(date +%s) - started) / 60 )) min"
note "Done. Tell Claude 'Meta setup done'; it reads $LOG_FILE (never $ENV_FILE)."
pause "Press Enter for the summary."

finish
}

run_wizard "$@"; exit
